import './studio.css'
import * as backend from './backend.js'
const $=id=>document.getElementById(id)
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))
let busy=false
function renderAuth(message=''){
 document.body.innerHTML=`<main class="studio-login"><div class="studio-card"><a href="/">← Billion Rush</a><div class="studio-mark">♛</div><div class="eyebrow">JUMI TECH • PRIVATE STAFF AREA</div><h1>Question Studio</h1><p>Admin and reviewer workspace. Player accounts cannot enter this area.</p><form id="staffForm"><input id="email" type="email" placeholder="Staff email" required><input id="password" type="password" placeholder="Password" required><button type="submit">${busy?'SIGNING IN…':'ENTER STUDIO'}</button></form><div class="studio-msg">${esc(message)}</div><small>Access is granted only when the Supabase profile role is <b>admin</b> or <b>reviewer</b>.</small></div></main>`
 $('staffForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;renderAuth('Signing in…');try{await backend.signIn($('email').value.trim(),$('password').value);await loadStudio()}catch(err){busy=false;renderAuth(err.message||'Login failed.')}}
}
async function loadStudio(){
 try{
  const user=await backend.getUser();
  if(!user) throw new Error('Please sign in.')
  const c=backend.getClient();
  const {data:profile,error}=await c.from('profiles').select('display_name,role').eq('id',user.id).single();
  if(error) throw error;
  if(!['admin','reviewer'].includes(profile.role)) { await backend.signOut(); throw new Error('Access denied. This account is not an admin or reviewer.') }
  renderStudio(user,profile)
  await refresh()
 }catch(err){busy=false;renderAuth(err.message||'Unable to open Question Studio.')}
}
function renderStudio(user,p){
 document.body.innerHTML=`<div class="studio-shell"><header><div><div class="eyebrow">JUMI TECH • QUESTION STUDIO</div><h1>Billion Rush</h1><p>Signed in as <b>${esc(p.display_name||user.email)}</b> · <span class="role">${esc(p.role).toUpperCase()}</span></p></div><div><button id="refresh">REFRESH</button><button id="logout">LOG OUT</button></div></header><main><section class="stats"><article>Total drafts<strong id="total">—</strong></article><article>Pending<strong id="pending">—</strong></article><article>Approved<strong id="approved">—</strong></article><article>Reports<strong id="reports">—</strong></article></section><section class="panel"><h2>AI Question Factory</h2><p>Gemini generates drafts only. Nothing reaches players until staff approves it.</p><div class="controls"><input id="count" type="number" min="1" max="20" value="10"><input id="category" value="mixed general knowledge"><button id="generate">GENERATE DRAFTS</button></div><div id="aiMsg"></div></section><section class="panel"><h2>Manual Question</h2><form id="create"><textarea id="questionText" placeholder="Question" required></textarea><div class="grid"><input id="a" placeholder="Option A" required><input id="b" placeholder="Option B" required><input id="c" placeholder="Option C" required><input id="d" placeholder="Option D" required></div><div class="grid"><select id="correct"><option>A</option><option>B</option><option>C</option><option>D</option></select><input id="cat" placeholder="Category" required><select id="diff"><option>easy</option><option selected>medium</option><option>hard</option><option>very_hard</option></select></div><textarea id="explanation" placeholder="Explanation" required></textarea><button type="submit">SAVE DRAFT</button><span id="createMsg"></span></form></section><section class="panel"><h2>Review Queue</h2><div id="queue">Loading…</div></section></main></div>`
 $('logout').onclick=async()=>{await backend.signOut();location.reload()};$('refresh').onclick=refresh;$('generate').onclick=generate;$('create').onsubmit=createQuestion
}
async function call(fn,body={}){const c=backend.getClient();if(!c)throw new Error('Supabase is not configured. Add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to your Vite environment.');const {data,error}=await c.functions.invoke(fn,{body});if(error)throw error;return data}
async function refresh(){try{const s=await call('studio-stats');$('total').textContent=s.total??'—';$('pending').textContent=s.pending??'—';$('approved').textContent=s.approved??'—';$('reports').textContent=s.openReports??'—';const q=await call('review-question',{action:'list'});$('queue').innerHTML=(q.questions||[]).map(x=>`<article class="question"><b>${esc(x.question_text)}</b><small>${esc(x.category)} · ${esc(x.difficulty)} · ${esc(x.status)}</small><div><button data-review="approve" data-id="${x.id}">APPROVE</button><button data-review="request_changes" data-id="${x.id}">CHANGES</button><button data-review="reject" data-id="${x.id}">REJECT</button></div></article>`).join('')||'<p>No questions awaiting review.</p>';document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await call('review-question',{action:'review',questionId:b.dataset.id,decision:b.dataset.review});await refresh()}catch(e){alert(e.message||'Review failed');b.disabled=false}})}catch(e){$('queue').textContent=e.message||'Unable to load Question Studio.'}}
async function generate(){const m=$('aiMsg');m.textContent='Generating drafts…';try{const r=await call('generate-questions',{count:Number($('count').value)||10,category:$('category').value.trim()||'mixed general knowledge'});m.textContent=`Generated ${r.generated||0} draft(s).`;await refresh()}catch(e){m.textContent=e.message||'Generation failed.'}}
async function createQuestion(e){e.preventDefault();const m=$('createMsg');try{await call('create-question',{questionText:$('questionText').value,optionA:$('a').value,optionB:$('b').value,optionC:$('c').value,optionD:$('d').value,correctOption:$('correct').value,explanation:$('explanation').value,category:$('cat').value,difficulty:$('diff').value});e.target.reset();m.textContent='Draft saved.';await refresh()}catch(err){m.textContent=err.message||'Could not save draft.'}}
(async()=>{try{if(backend.isConfigured() && (await backend.getUser())) await loadStudio();else renderAuth()}catch{renderAuth()}})()
